function beanStyleKey(bean){const candidate=Number(bean?.value??1),value=Number.isFinite(candidate)?candidate:1;if(bean?.effect==='zero'||value===0)return 'zero:0';if(bean?.effect==='subtract'||value<0)return Math.abs(value)>=100?'subtract:-100':'subtract:-10';const key='score:'+value;return beanStyles[key]?key:'score:1';}
