function label(parent,text,x,y,z,options={}){const sprite=new T.Sprite(textLabel(text,options));sprite.position.set(x,y,z);sprite.scale.set(options.scale||3.4,(options.scale||3.4)*(options.height||96)/(options.width||256),1);parent.add(sprite);return sprite;}
